const D = { scale:1, density:.5, energy:.6, hue:330, speed:1, misreg:.5, x:.5, y:.42, style:'riso', pal:'fluoro', act:'rise', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style, blueprint=style==='blueprint', mono=style==='mono', sunset=style==='sunset';
const en=clp(P.energy,0,1)*(.5+.5*K.intensity);
const dens=clp(P.density,0,1);

// ---- palette (two ink hues) ----
const PALS={fluoro:[330,205], toxic:[92,26], plum:[282,352], sea:[178,224]};
const base=PALS[P.pal]||PALS.fluoro;
const hOff=P.hue-330;
let hA=md(base[0]+hOff,360), hB=md(base[1]+hOff,360);
// paper
let paperH=45,paperS=10,paperB=87;
if(blueprint){paperH=md(hB,360);paperS=68;paperB=32;}
else if(mono){paperH=40;paperS=6;paperB=88;}

// ---- build cached ink buffers, keyed on size/seed/style/densBucket/pal ----
const dBucket=Math.round(dens*4);
const key=W+'x'+Hh+'|'+P.seed+'|'+style+'|'+P.pal+'|'+dBucket;
if(S.key!==key){
  S.key=key;
  const gA=createGraphics(W,Hh), gB=createGraphics(W,Hh);
  [gA,gB].forEach(g=>{g.colorMode(g.HSB,360,100,100,100);g.noStroke();g.clear();});
  const sp=Math.max(5, u*(0.030 - dens*0.020)); // dot spacing: dense->finer
  const jit=sp*0.28;
  // sky wash into gA (dots grow toward top)
  const skyBot=Hh*0.62;
  for(let y=-sp; y<skyBot+sp; y+=sp){
    for(let x=-sp; x<W+sp; x+=sp){
      const i=(x*13.1+y*7.7);
      const gy=1-clp(y/skyBot,0,1);           // 1 at top
      let r=sp*0.30 + sp*0.42*gy;
      r*= .7+ .6*fr(i);
      if(blueprint) continue;                  // blueprint drawn as lines below
      const px=x+(fr(i+1)-.5)*jit, py=y+(fr(i+2)-.5)*jit;
      gA.fill(hA, mono?0:78, mono?12:96, 100);
      gA.circle(px,py,r*2);
    }
  }
  // hills into gB (dots on stacked hill bands)
  const nHills=3;
  for(let hI=0; hI<nHills; hI++){
    const hy=Hh*(0.60+hI*0.14);
    const amp=u*(0.05+0.03*fr(hI*9+5));
    const ph=fr(hI*3+2)*TAU, wl=1.2+fr(hI*4)*1.6;
    for(let x=-sp; x<W+sp; x+=sp){
      const top=hy - amp*Math.sin(x/W*TAU*wl+ph) - amp*0.4*Math.sin(x/W*TAU*wl*2.3+ph);
      for(let y=top; y<Hh+sp; y+=sp){
        const i=(x*5.3+y*9.1+hI*777);
        const dpth=clp((y-top)/(Hh-top+1),0,1);
        let r=sp*0.24 + sp*0.40*(1-dpth);
        r*= .7+.6*fr(i);
        if(blueprint) continue;
        const px=x+(fr(i+1)-.5)*jit, py=y+(fr(i+2)-.5)*jit;
        gB.fill(hB, mono?0:80, mono?10:92, 100);
        gB.circle(px,py,r*2);
      }
    }
  }
  // blueprint: white schematic line art on gA
  if(blueprint){
    gA.noFill(); gA.stroke(45,4,98,90);
    for(let hI=0; hI<nHills; hI++){
      const hy=Hh*(0.58+hI*0.13), amp=u*(0.05+0.03*fr(hI*9+5));
      const ph=fr(hI*3+2)*TAU, wl=1.2+fr(hI*4)*1.6;
      gA.strokeWeight(1.1+hI*0.5); gA.beginShape();
      for(let x=-4;x<=W+4;x+=8){const yy=hy-amp*Math.sin(x/W*TAU*wl+ph)-amp*0.4*Math.sin(x/W*TAU*wl*2.3+ph);gA.vertex(x,yy);}
      gA.endShape();
    }
    // grid ticks
    gA.strokeWeight(0.6); gA.stroke(45,4,98,28);
    const gs=u*0.09;
    for(let x=0;x<W;x+=gs)gA.line(x,0,x,Hh);
    for(let y=0;y<Hh;y+=gs)gA.line(0,y,W,y);
  }
  S.gA=gA; S.gB=gB; S.sp=sp;
  // sun sprite (small buffer) — halftone disc / rings
  const SR=Math.ceil(u*0.42);
  const gs2=createGraphics(SR*2,SR*2); gs2.colorMode(gs2.HSB,360,100,100,100); gs2.noStroke(); gs2.clear();
  const ssp=Math.max(4,SR*(0.10-dens*0.055));
  if(blueprint){
    gs2.noFill(); gs2.stroke(45,4,98,92);
    for(let rr=SR*0.25; rr<SR*0.98; rr+=SR*0.16){gs2.strokeWeight(1.0);gs2.circle(SR,SR,rr*2);}
    for(let a=0;a<TAU;a+=TAU/24){gs2.strokeWeight(0.8);gs2.line(SR,SR,SR+Math.cos(a)*SR*0.96,SR+Math.sin(a)*SR*0.96);}
  } else {
    for(let y=-ssp;y<SR*2+ssp;y+=ssp){
      for(let x=-ssp;x<SR*2+ssp;x+=ssp){
        const dx=x-SR,dy=y-SR,rd=Math.hypot(dx,dy)/SR;
        if(rd>1.02)continue;
        let r=ssp*0.62*(1-rd*0.55); r*=.75+.5*fr(x*3.1+y*2.7);
        gs2.fill(hA, mono?0:80, mono?14:98,100);
        gs2.circle(x,y,r*2);
      }
    }
  }
  S.sun=gs2; S.SR=SR;
}

// ---- LIVE COMPOSITE ----
noStroke();
background(paperH,paperS,paperB);

const kick=K.pulse*.5 + A.bass*.7;
const drift=K.t*0.6;
// misregistration offsets (jitter on beat + continuous drift, never re-phasing)
const mA=P.misreg*u*0.012*(0.6+en);
const offAx=Math.cos(drift*0.7)*mA + Math.sin(K.beat*TAU*P.speed)*mA*0.4*(0.3+kick);
const offAy=Math.sin(drift*0.9)*mA*0.8;
const offBx=-Math.cos(drift*0.5+1.1)*mA*1.1 - Math.sin(K.beat*TAU*P.speed+0.7)*mA*0.4*(0.3+kick);
const offBy=-Math.sin(drift*0.6+0.4)*mA*0.7;

const oldBlend=drawingContext.globalCompositeOperation;
if(!blueprint&&!sunset) blendMode(MULTIPLY);

// sunset: smooth vertical duotone gradient instead of dots
if(sunset){
  for(let y=0;y<Hh;y+=3){
    const t=y/Hh; const h=md(hA+(hB-hA)*t,360);
    fill(h, 55+30*(1-t), 96-40*t, 100); rect(0,y,W,3);
  }
}

// sky ink A
image(S.gA, offAx, offAy);

// rotating ray burst behind sun (ink A)
const sunX=P.x*W, sunY=P.y*Hh - u*0.02*Math.sin(K.t*0.5) ;
// act arc: sun height drifts over minutes
let rise=0;
if(P.act==='set'){ rise = -0.10*u*(0.5+0.5*Math.sin(K.t*0.05)); }
else if(P.act==='rise'){ rise = 0.12*u*Math.sin(K.t*0.045); }
const scy=sunY - rise;
push(); translate(sunX,scy); rotate(K.t*0.12*P.speed + drift*0.05);
const nrays=blueprint?0:22; const rayLen=u*0.30*(0.7+en)*P.scale*(1+0.15*kick);
if(!mono){for(let i=0;i<nrays;i++){const a=i/nrays*TAU; const w=TAU/nrays*0.42;
  fill(hA,70,90, 22+18*en);
  triangle(Math.cos(a)*u*0.18*P.scale,Math.sin(a)*u*0.18*P.scale,
    Math.cos(a-w)*rayLen,Math.sin(a-w)*rayLen, Math.cos(a+w)*rayLen,Math.sin(a+w)*rayLen);
}}
pop();

// sun sprite — pulse breathe + slow spin (gives blueprint ticks visible motion)
const sunScale=P.scale*(0.86+0.10*K.swell+0.10*kick);
const sw=S.SR*2*sunScale;
push(); translate(sunX,scy); rotate(-K.t*0.08*P.speed - drift*0.03);
image(S.sun, -sw/2, -sw/2, sw, sw); pop();

// hills ink B
image(S.gB, offBx, offBy);

// drifting cloud bands (real-time scroll), few translucent bars
if(!blueprint){
  blendMode(MULTIPLY);
  const nb=Math.floor(2+dens*4);
  for(let i=0;i<nb;i++){
    const by=Hh*(0.10+0.30*fr(i*7+3));
    const bh=u*(0.012+0.02*fr(i*5+1));
    const sx=md(-drift*(20+i*8)*(0.6+en) + fr(i*3)*W, W+u*0.6)-u*0.3;
    fill(hB, 40, 80, 10+8*en);
    ellipse(sx, by+u*0.02*Math.sin(K.t*0.3+i), u*(0.20+0.14*fr(i*9)), bh*3);
  }
}

// seal / paper vignette to keep luminance safe
blendMode(BLEND);
// vermilion-free light grain on beat for texture (few dots, cheap)
if(en>0.02){
  const nd=Math.floor(30*dens);
  fill(mono?0:hB, mono?0:30, mono?8:20, 6+10*kick);
  for(let i=0;i<nd;i++){const gx=frc(fr(i+Math.floor(K.beat))*1.7)*W, gy=frc(fr(i+7+Math.floor(K.beat))*1.3)*Hh; circle(gx,gy,u*0.004);}
}
// corner registration marks (static graphic ident)
stroke(mono?0:hA, mono?0:60, mono?20:70, 55); strokeWeight(1.2); noFill();
const m=u*0.03;
[[m,m],[W-m,m],[m,Hh-m],[W-m,Hh-m]].forEach(c=>{line(c[0]-6,c[1],c[0]+6,c[1]);line(c[0],c[1]-6,c[0],c[1]+6);});
noStroke();

blendMode(BLEND); drawingContext.globalCompositeOperation=oldBlend; drawingContext.shadowBlur=0;
